def local_now(now=None):
    """Return an injected naive clock or Zurich wall time, independent of the host timezone."""
    if now is not None:
        if not isinstance(now, datetime) or now.tzinfo is not None:
            raise ValueError('Injected now must be a naive Zurich datetime.')
        return now
    return datetime.now(ZoneInfo(TIMEZONE_NAME)).replace(tzinfo=None)
